/* Vista de solo lectura del campo, para previsualizar un ejercicio de la
   biblioteca sin salir de Ejercicios ni abrir la pizarra real. Dibuja las
   mismas fichas y trazos que devuelve ex.build(), pero sin arrastre, sin
   herramientas y sin estado propio: es una foto del montaje, no un editor.
   Coordenadas en el mismo lienzo 1000×640 que usa la pizarra para el campo
   entero, así que ex.build() vale tal cual para las dos vistas. */
const exPathOf = (pts) => pts.map((p, i) => (i === 0 ? `M${p.x},${p.y}` : `L${p.x},${p.y}`)).join(" ");
const exWavyPath = (a, b) => {
  const dx = b.x - a.x, dy = b.y - a.y, len = Math.hypot(dx, dy) || 1;
  const ux = dx / len, uy = dy / len, nx = -uy, ny = ux;
  const step = 16, amp = 7;
  let d = `M${a.x},${a.y}`;
  for (let i = step; i < len - step; i += step) {
    const s = (Math.round(i / step) % 2 === 0 ? 1 : -1) * amp;
    d += ` L${a.x + ux * i + nx * s},${a.y + uy * i + ny * s}`;
  }
  return `${d} L${b.x},${b.y}`;
};
const exTokenFill = (ty) => (ty === "home" ? "#FFFFFF" : ty === "away" ? "#36454F" : ty === "ball" ? "#FFFFFF" : ty === "disc" ? "#9FB0BA" : ty === "goal" ? "#E6EAEC" : "#C0C8CD");
const exDrawShape = (s) => {
  const col = s.color || "#FFFFFF";
  const sw = s.width || 4;
  const common = { fill: "none", stroke: col, strokeWidth: sw, strokeLinecap: "round", strokeLinejoin: "round" };
  const k = s.id ?? Math.random();
  if (s.tool === "text") return <text key={k} x={s.pts[0].x} y={s.pts[0].y} fill={col} fontSize={22 + sw * 2} fontFamily="Barlow Condensed, sans-serif" fontWeight="700">{s.text}</text>;
  if (s.tool === "zone") { const a = s.pts[0], b = s.pts[1]; return <rect key={k} x={Math.min(a.x, b.x)} y={Math.min(a.y, b.y)} width={Math.abs(b.x - a.x)} height={Math.abs(b.y - a.y)} {...common} fill={col} fillOpacity="0.13" strokeDasharray="8 6" />; }
  if (s.tool === "circle") { const a = s.pts[0], b = s.pts[1]; return <circle key={k} cx={a.x} cy={a.y} r={Math.hypot(b.x - a.x, b.y - a.y)} {...common} fill={col} fillOpacity="0.10" />; }
  if (s.tool === "pass") return <path key={k} d={exPathOf(s.pts)} strokeDasharray="10 10" markerEnd="url(#exArrow)" {...common} />;
  if (s.tool === "dribble") return <path key={k} d={exWavyPath(s.pts[0], s.pts[s.pts.length - 1])} markerEnd="url(#exArrow)" {...common} />;
  if (s.tool === "arrow") return <path key={k} d={exPathOf(s.pts)} markerEnd="url(#exArrow)" {...common} />;
  return <path key={k} d={exPathOf(s.pts)} {...common} />;
};
const ExerciseBoard = ({ ex }) => {
  const { tokens = [], shapes = [] } = ex?.build ? ex.build() : {};
  return (
    <svg viewBox="0 0 1000 640" className="w-full rounded-lg border pointer-events-none select-none"
      style={{ borderColor: C.line, background: "#152219", aspectRatio: "1000/640" }}>
      <defs>
        <marker id="exArrow" markerWidth="10" markerHeight="10" refX="7" refY="3" orient="auto"><path d="M0,0 L7,3 L0,6 Z" fill="#FFFFFF" /></marker>
      </defs>
      {[0, 1, 2, 3, 4, 5, 6, 7].map((i) => <rect key={i} x={i * 125} y="0" width="125" height="640" fill={i % 2 ? "#17251D" : "#152219"} />)}
      <g stroke="rgba(255,255,255,0.55)" strokeWidth="3" fill="none">
        <rect x="12" y="12" width="976" height="616" /><line x1="500" y1="12" x2="500" y2="628" /><circle cx="500" cy="320" r="70" />
        <rect x="12" y="200" width="120" height="240" /><rect x="868" y="200" width="120" height="240" />
        <rect x="12" y="270" width="45" height="100" /><rect x="943" y="270" width="45" height="100" />
      </g>
      {shapes.map((s) => exDrawShape(s))}
      {tokens.map((tk, i) => (
        <g key={tk.id ?? i}>
          {tk.type === "cone"
            ? <path d={`M${tk.x},${tk.y - 16} L${tk.x + 14},${tk.y + 12} L${tk.x - 14},${tk.y + 12} Z`} fill={exTokenFill(tk.type)} stroke={tk.type === "away" ? "#FFFFFF" : "#36454F"} strokeWidth="2" />
            : tk.type === "disc"
            ? <ellipse cx={tk.x} cy={tk.y} rx="14" ry="7" fill={exTokenFill(tk.type)} stroke={tk.type === "away" ? "#FFFFFF" : "#36454F"} strokeWidth="2" />
            : tk.type === "goal"
            ? <g><rect x={tk.x - 30} y={tk.y - 12} width="60" height="24" fill="none" stroke={exTokenFill(tk.type)} strokeWidth="4" />
                <line x1={tk.x - 30} y1={tk.y - 12} x2={tk.x - 30} y2={tk.y + 12} stroke={exTokenFill(tk.type)} strokeWidth="4" />
                <line x1={tk.x + 30} y1={tk.y - 12} x2={tk.x + 30} y2={tk.y + 12} stroke={exTokenFill(tk.type)} strokeWidth="4" /></g>
            : <>
                <circle cx={tk.x} cy={tk.y} r={tk.type === "ball" ? 13 : 20} fill={exTokenFill(tk.type)} stroke={tk.type === "away" ? "#FFFFFF" : "#36454F"} strokeWidth={tk.type === "ball" ? 2 : 3} />
                {tk.label && <text x={tk.x} y={tk.y} textAnchor="middle" dominantBaseline="central" fontSize="20" fontFamily="Barlow Condensed, sans-serif" fontWeight="700" fill={tk.type === "away" ? "#FFFFFF" : "#36454F"}>{tk.label}</text>}
              </>}
        </g>
      ))}
    </svg>
  );
};

/* Desplegable de la pizarra: mismo comportamiento para ejercicios y jugadas.
   Se cierra al pulsar fuera y con Escape, y el panel se ancla al botón. */
function WbMenu({ label, icon, count, AC, wide = false, children }) {
  const [open, setOpen] = useState(false);
  const [pos, setPos] = useState(null);
  const box = useRef(null);
  const panel = useRef(null);
  /* La barra de herramientas se desliza con overflow-x en móvil, y eso
     recorta en el eje Y cualquier hijo absoluto por dentro (es la regla CSS
     que convierte el overflow-y en "auto" en cuanto el x deja de ser
     "visible"): el desplegable se abría pero quedaba invisible o sin poder
     tocarlo. En pantalla completa girada pasaba lo mismo, doblado con el giro
     del contenedor. Sacándolo por portal a <body> y calculando su sitio con
     las coordenadas reales del botón (getBoundingClientRect, que ya vienen
     con cualquier transformación aplicada) se escapa de ambos recortes. */
  const situar = () => {
    const r = box.current?.getBoundingClientRect();
    if (!r) return;
    const w = wide ? Math.min(window.innerWidth * 0.88, 380) : Math.min(window.innerWidth * 0.8, 240);
    const left = Math.min(Math.max(8, r.left), window.innerWidth - w - 8);
    const gap = 4;
    /* En pantalla completa girada, el botón puede acabar pegado al borde REAL
       de la pantalla (la rotación cambia qué es "abajo"): abrir siempre hacia
       abajo lo dejaba en una tira de 20-30 px. Se mide cuánto hueco real hay
       arriba y abajo del botón y se abre hacia el lado que tenga más. */
    const abajo = window.innerHeight - r.bottom - gap;
    const arriba = r.top - gap;
    if (abajo >= 140 || abajo >= arriba) {
      setPos({ left, top: r.bottom + gap, width: w, maxHeight: Math.max(120, Math.min(abajo, 420)) });
    } else {
      setPos({ left, bottom: window.innerHeight - r.top + gap, width: w, maxHeight: Math.max(120, Math.min(arriba, 420)) });
    }
  };
  useEffect(() => {
    if (!open) return;
    situar();
    const out = (e) => { if (!box.current?.contains(e.target) && !panel.current?.contains(e.target)) setOpen(false); };
    const esc = (e) => { if (e.key === "Escape") { e.stopPropagation(); setOpen(false); } };
    document.addEventListener("pointerdown", out);
    document.addEventListener("keydown", esc, true);
    window.addEventListener("resize", situar);
    window.addEventListener("scroll", situar, true);
    return () => {
      document.removeEventListener("pointerdown", out); document.removeEventListener("keydown", esc, true);
      window.removeEventListener("resize", situar); window.removeEventListener("scroll", situar, true);
    };
  }, [open]); // eslint-disable-line
  return (
    <div className="relative" ref={box}>
      <button onClick={() => setOpen((v) => !v)} aria-expanded={open} aria-haspopup="true"
        className="h-9 px-2.5 shrink-0 rounded-lg border text-xs font-display uppercase tracking-wide inline-flex items-center gap-1"
        style={{ borderColor: open ? AC : C.line, background: open ? AC : C.panel2, color: open ? "#141414" : C.chalk }}>
        <span>{icon}</span>
        {/* La etiqueta también en el móvil: un icono suelto no dice si eso son
            los ejercicios, los ABP o las jugadas, y con la fila deslizante hay
            sitio de sobra. */}
        <span className="whitespace-nowrap">{label}</span>
        {count != null && <span className="tabular-nums opacity-70">{count}</span>}
        <span className="text-[9px]">▾</span>
      </button>
      {open && pos && createPortal(
        <div ref={panel} className="fixed z-[999] rounded-lg border shadow-2xl overflow-auto"
          style={{ borderColor: C.line, background: C.panel, left: pos.left, top: pos.top, bottom: pos.bottom, width: pos.width, maxHeight: pos.maxHeight }}
          onClick={(e) => e.stopPropagation()}>
          {typeof children === "function" ? children(() => setOpen(false)) : children}
        </div>,
        document.body
      )}
    </div>
  );
}

/* ================= PLANIFICACIÓN DE TEMPORADA =================
   Los cuatro pilares sobre los que se reparte el trabajo del año. No es una
   taxonomía académica: son las cuatro cosas que un entrenador de base decide
   cuánto peso llevan en cada mes de la temporada. */
const PILARES = [
  { k: "fisico", icon: "◈", color: "#36454F", name: { es: "Físico", en: "Physical", fr: "Physique", de: "Athletik", pt: "Físico" },
    desc: { es: "Resistencia, velocidad, fuerza y prevención de lesiones.", en: "Endurance, speed, strength and injury prevention." } },
  { k: "tactico", icon: "⬡", color: "#5A6B75", name: { es: "Táctico", en: "Tactical", fr: "Tactique", de: "Taktik", pt: "Tático" },
    desc: { es: "Sistema, salida de balón, presión y ocupación de espacios.", en: "System, build-up, pressing and use of space." } },
  { k: "mental", icon: "♦", color: "#708090", name: { es: "Mental", en: "Mental", fr: "Mental", de: "Mental", pt: "Mental" },
    desc: { es: "Concentración, gestión del error, cohesión y competitividad.", en: "Focus, handling mistakes, cohesion and competitiveness." } },
  { k: "abp", icon: "⚐", color: "#4F6470", name: { es: "ABP", en: "Set pieces", fr: "Coups arrêtés", de: "Standards", pt: "Bolas paradas" },
    desc: { es: "Córners, faltas, saques de banda y de puerta.", en: "Corners, free kicks, throw-ins and goal kicks." } },
];
/* Temporada de fútbol base: de septiembre a junio. */
/* Qué ejercicios pegan con cada pilar. Sirve para que al marcar un mes como
   "físico" la app proponga trabajo de verdad en vez de dejar la casilla marcada
   y ya. Las claves son las categorías reales de EXERCISES. */
const PILAR_CATS = {
  fisico: ["fitness", "warmup", "duel"],
  tactico: ["buildup", "press", "defense", "rondo", "cross", "finish"],
  mental: ["duel", "rondo", "infantil"],
  abp: ["setpiece", "cross"],
};
const ejerciciosDePilar = (k) => {
  const cats = PILAR_CATS[k] || [];
  return EXERCISES.filter((e) => cats.includes(e.cat));
};

/* Nombre legible de cada tipo de evento del acta. Antes se pintaba la clave
   tal cual y en el acta salía "golRival", que no es castellano; y era fijo
   en español sin importar el idioma de quien lo lee. */
const EVENTO_TXT = {
  gol: { es: "Gol", en: "Goal", fr: "But", de: "Tor", pt: "Golo" },
  golRival: { es: "Gol del rival", en: "Opponent goal", fr: "But adverse", de: "Gegentor", pt: "Golo do adversário" },
  cambio: { es: "Cambio", en: "Substitution", fr: "Changement", de: "Wechsel", pt: "Substituição" },
  tarjeta: { es: "Tarjeta", en: "Card", fr: "Carton", de: "Karte", pt: "Cartão" },
  falta: { es: "Falta", en: "Foul", fr: "Faute", de: "Foul", pt: "Falta" },
  nota: { es: "Nota", en: "Note", fr: "Note", de: "Notiz", pt: "Nota" },
  periodo: { es: "Cambio de parte", en: "Period change", fr: "Changement de période", de: "Periodenwechsel", pt: "Mudança de período" },
  penalti: { es: "Penalti", en: "Penalty", fr: "Penalty", de: "Elfmeter", pt: "Penálti" },
};
const nombreEvento = (k, lang = "es") => EVENTO_TXT[k]?.[lang] || EVENTO_TXT[k]?.es || k;
/* Colores de tarjeta: amarilla, segunda amarilla (expulsión) y roja directa. */
const CARD_TIPOS = [
  { k: "amarilla", icon: "🟨", name: { es: "Amarilla", en: "Yellow", fr: "Jaune", de: "Gelb", pt: "Amarelo" } },
  { k: "doble", icon: "🟨🟨", name: { es: "2ª amarilla", en: "2nd yellow", fr: "2e jaune", de: "2. Gelb", pt: "2º amarelo" } },
  { k: "roja", icon: "🟥", name: { es: "Roja", en: "Red", fr: "Rouge", de: "Rot", pt: "Vermelho" } },
];
const cardNombre = (k, lang = "es") => { const c = CARD_TIPOS.find((x) => x.k === k); return c ? (c.name[lang] || c.name.es) : ""; };
/* Descripción completa de una fila del acta: cambia de tarjeta (color +
   jugador), cambio de parte (nombre de la parte) y penalti (marcado/fallado,
   propio o rival) a la línea genérica "tipo — jugador" del resto. */
const descEvento = (e, lang = "es") => {
  if (e.type === "periodo") return e.periodoNombre || nombreEvento("periodo", lang);
  if (e.type === "tarjeta" && e.card) {
    const icon = CARD_TIPOS.find((c) => c.k === e.card)?.icon || "";
    return `${icon} ${cardNombre(e.card, lang)}${e.player ? " — " + e.player : ""}`;
  }
  if (e.type === "penalti") {
    const resu = e.resultado === "fallo" ? T(lang, "mt.penMissed") : T(lang, "mt.penScored");
    const lado = e.lado === "them" ? T(lang, "mt.penRival") : T(lang, "mt.penOwn");
    return `${lado} · ${resu}${e.player ? " — " + e.player : ""}`;
  }
  return `${nombreEvento(e.type, lang)}${e.player ? " — " + e.player : ""}`;
};
/* Partes del partido, incluida prórroga y penaltis -no todos los partidos
   de fútbol base los tienen, pero cuando toca (eliminatorias, copas) hace
   falta poder registrarlos igual que una parte normal. */
const PERIODOS = [
  { k: "p1", n: 1, name: { es: "1ª parte", en: "1st half", fr: "1re mi-temps", de: "1. Halbzeit", pt: "1ª parte" } },
  { k: "p2", n: 2, name: { es: "2ª parte", en: "2nd half", fr: "2e mi-temps", de: "2. Halbzeit", pt: "2ª parte" } },
  { k: "pr1", n: 3, name: { es: "Prórroga 1", en: "Extra time 1", fr: "Prolongation 1", de: "Verlängerung 1", pt: "Prolongamento 1" } },
  { k: "pr2", n: 4, name: { es: "Prórroga 2", en: "Extra time 2", fr: "Prolongation 2", de: "Verlängerung 2", pt: "Prolongamento 2" } },
  { k: "pen", n: null, name: { es: "Penaltis", en: "Penalties", fr: "Tirs au but", de: "Elfmeterschießen", pt: "Grandes penalidades" } },
];
/* Duración de la prórroga: 15 minutos por parte es el estándar en todas las
   competiciones de base que juegan prórroga, así que no hace falta que sea
   configurable como sí lo es la duración de la parte normal. */
const ET_HALF_MIN = 15;

const MESES_TEMP = [
  { k: 9, es: "Septiembre" }, { k: 10, es: "Octubre" }, { k: 11, es: "Noviembre" }, { k: 12, es: "Diciembre" },
  { k: 1, es: "Enero" }, { k: 2, es: "Febrero" }, { k: 3, es: "Marzo" }, { k: 4, es: "Abril" },
  { k: 5, es: "Mayo" }, { k: 6, es: "Junio" },
];

